import sys, os, csv, json, gzip, io, glob
from datetime import datetime, timedelta, timezone, date
from fractions import Fraction
from decimal import Decimal
from zoneinfo import ZoneInfo

HEADER_NAMES = {"Badge", "Punch", "Date", "Time", "Zone", "Terminal", "Record"}


def read_text(path):
    with open(path, "rb") as f:
        b = f.read()
    if b[:2] == b"\x1f\x8b":
        b = gzip.decompress(b)
    t = b.decode("utf-8")
    if t.startswith("\ufeff"):
        t = t[1:]
    return [l for l in t.replace("\r\n", "\n").replace("\r", "\n").split("\n") if l.strip() != ""]


def local_to_utc(naive, zone, fold=0):
    return int(naive.replace(tzinfo=zone, fold=fold).timestamp())


def std_offset(zone):
    for m in (1, 7, 4, 10):
        d = datetime(2026, m, 15, 12, tzinfo=zone)
        if not d.dst():
            return int(d.utcoffset().total_seconds())
    return int(datetime(2026, 1, 15, tzinfo=zone).utcoffset().total_seconds())


def epoch_of_utc_ts(s):
    return int(datetime.fromisoformat(s.replace("Z", "+00:00")).timestamp())


def iso_epoch(s):
    d = datetime.fromisoformat(s.strip().replace("Z", "+00:00"))
    return int(d.timestamp())


def parse_abbr(lines, zone):
    out = []
    hdr = None
    for line in lines:
        row = next(csv.reader([line]))
        row = [c.strip() for c in row]
        if "Badge" in row and "Punch" in row:
            hdr = row
            continue
        if hdr is None:
            continue
        r = dict(zip(hdr, row))
        m, d, y = map(int, r["Date"].split("/"))
        t = r["Time"].strip().upper()
        ampm = None
        if t.endswith("AM") or t.endswith("PM"):
            ampm = t[-2:]
            t = t[:-2].strip()
        h, mi, s = map(int, t.split(":"))
        if ampm:
            h = h % 12 + (12 if ampm == "PM" else 0)
        fold = 0 if r["Zone"].strip().upper().endswith("DT") else 1
        ts = local_to_utc(datetime(y, m, d, h, mi, s), zone, fold)
        out.append((r["Record"], r["Badge"], r["Punch"].upper(), ts))
    return out


def parse_epoch(lines):
    out = []
    schema = 1
    for line in lines:
        o = json.loads(line)
        if "schema" in o and "id" not in o and "punch_id" not in o:
            schema = int(o["schema"])
            continue
        if o.get("heartbeat"):
            continue
        if schema == 2 or "punch_id" in o:
            pid, emp, dr = o["punch_id"], o["employee"], o["direction"]
            ts = int(o["epoch_ms"]) // 1000
        else:
            pid, emp, dr = o["id"], o["emp"], o["dir"]
            ts = int(o["ts_ms"]) // 1000 if "ts_ms" in o else int(o["ts"])
        out.append((str(pid), emp, dr.upper(), ts))
    return out


def parse_offset(lines):
    out = []
    rd = csv.reader(lines, delimiter=";", quotechar='"')
    hdr = None
    for row in rd:
        if hdr is None or "punch_id" in row:
            hdr = row
            continue
        r = dict(zip(hdr, row))
        dr = "IN" if r["event"].strip() == "clock_in" else "OUT"
        out.append((r["punch_id"], r["employee"], dr, iso_epoch(r["timestamp"])))
    return out


def parse_legacy(lines, zone):
    out = []
    off = std_offset(zone)
    cur = off
    for line in lines:
        c = line[0]
        if c == "H":
            o = line[13:18].strip()
            if len(o) == 5 and o[0] in "+-":
                sec = (int(o[1:3]) * 3600 + int(o[3:5]) * 60)
                cur = sec if o[0] == "+" else -sec
            else:
                cur = off
        elif c == "D":
            pid = line[1:9]
            badge = line[9:15].strip()
            dr = "IN" if line[15] == "I" else "OUT"
            dt = datetime.strptime(line[16:30], "%Y%m%d%H%M%S").replace(tzinfo=timezone.utc)
            ts = int(dt.timestamp()) - cur
            out.append((pid, "E" + badge, dr, ts))
    return out


def parse_de(lines, zone):
    out = []
    hdr = None
    for line in lines:
        row = line.split("\t")
        if hdr is None or "Ausweis" in row:
            hdr = row
            continue
        r = dict(zip(hdr, row))
        d, m, y = map(int, r["Datum"].split("."))
        h, mi = map(int, r["Uhrzeit"].split(":")[:2])
        fold = 0 if r["Zeitzone"].strip().upper() == "MESZ" else 1
        ts = local_to_utc(datetime(y, m, d, h, mi), zone, fold)
        out.append((r["Nr"], r["Ausweis"], "IN" if r["Buchung"].strip() == "K" else "OUT", ts))
    return out


def parse_local_csv(lines, zone):
    out = []
    rd = csv.reader(lines)
    hdr = None
    for row in rd:
        if hdr is None or "employee_id" in row:
            hdr = row
            continue
        r = dict(zip(hdr, row))
        ts = local_to_utc(datetime.strptime(r["local_time"].strip(), "%Y-%m-%d %H:%M:%S"), zone, 0)
        out.append((r["punch_ref"], r["employee_id"], r["direction"].upper(), ts))
    return out


def parse_local_jsonl(lines, zone):
    out = []
    for line in lines:
        o = json.loads(line)
        p = o.get("punch")
        if not p:
            continue
        ts = local_to_utc(datetime.strptime(p["at"].strip(), "%Y-%m-%d %H:%M:%S"), zone, 0)
        out.append((str(p["id"]), p["badge"], p["type"].upper(), ts))
    return out


def round_punch(ts, zone):
    off = int(datetime.fromtimestamp(ts, zone).utcoffset().total_seconds())
    loc = ts + off
    r = (loc + 180) // 360 * 360
    return r - off


def night_minutes(a, b, zone):
    # a,b epoch seconds
    tot = 0
    d0 = datetime.fromtimestamp(a, zone).date() - timedelta(days=1)
    d1 = datetime.fromtimestamp(b, zone).date()
    d = d0
    while d <= d1:
        s = local_to_utc(datetime(d.year, d.month, d.day, 22), zone)
        n = d + timedelta(days=1)
        e = local_to_utc(datetime(n.year, n.month, n.day, 6), zone)
        lo, hi = max(a, s), min(b, e)
        if hi > lo:
            tot += hi - lo
        d += timedelta(days=1)
    return tot // 60


def main(inp, outp):
    period = json.load(open(os.path.join(inp, "period.json")))
    pstart = date.fromisoformat(period["start"])
    pend = date.fromisoformat(period["end"])
    cutoff = epoch_of_utc_ts(period["corrections_cutoff"])
    sites = {}
    with open(os.path.join(inp, "sites.csv"), newline="", encoding="utf-8-sig") as f:
        for r in csv.DictReader(f):
            sites[r["site"].strip()] = (ZoneInfo(r["timezone"].strip()), r["format"].strip())
    emps = {}
    with open(os.path.join(inp, "employees.csv"), newline="", encoding="utf-8-sig") as f:
        for r in csv.DictReader(f):
            emps[r["employee_id"].strip()] = r["home_site"].strip()
    rates = {}
    with open(os.path.join(inp, "rates.csv"), newline="", encoding="utf-8-sig") as f:
        for r in csv.DictReader(f):
            rates.setdefault(r["employee_id"].strip(), []).append(
                (date.fromisoformat(r["effective_from"].strip()), Fraction(Decimal(r["hourly_rate"].strip()))))
    for v in rates.values():
        v.sort()

    punches = {}   # (site,id) -> [emp, dir, ts]
    existed = set()
    for site, (zone, fmt) in sites.items():
        d = os.path.join(inp, "exports", site)
        if not os.path.isdir(d):
            continue
        for path in sorted(glob.glob(os.path.join(d, "**", "*"), recursive=True)):
            if not os.path.isfile(path):
                continue
            lines = read_text(path)
            if fmt == "abbr-csv": recs = parse_abbr(lines, zone)
            elif fmt == "epoch-jsonl": recs = parse_epoch(lines)
            elif fmt == "offset-csv": recs = parse_offset(lines)
            elif fmt == "legacy-fixed": recs = parse_legacy(lines, zone)
            elif fmt == "de-tsv": recs = parse_de(lines, zone)
            elif fmt == "local-csv": recs = parse_local_csv(lines, zone)
            elif fmt == "local-jsonl": recs = parse_local_jsonl(lines, zone)
            else: continue
            for pid, emp, dr, ts in recs:
                k = (site, pid)
                if k not in punches:
                    punches[k] = [emp, dr, ts]
                    existed.add(k)

    # corrections
    corr = []
    cdir = os.path.join(inp, "corrections")
    if os.path.isdir(cdir):
        for path in sorted(glob.glob(os.path.join(cdir, "**", "*"), recursive=True)):
            if not os.path.isfile(path):
                continue
            lines = read_text(path)
            for r in csv.DictReader(lines):
                corr.append({k: (v or "").strip() for k, v in r.items() if k})
    corr = [c for c in corr if epoch_of_utc_ts(c["issued_at"]) <= cutoff]
    corr.sort(key=lambda c: (epoch_of_utc_ts(c["issued_at"]), c["correction_id"]))
    applied = 0
    voided = set()
    for c in corr:
        k = (c["site"], c["punch_id"])
        a = c["action"]
        if a == "void":
            if k in punches and k not in voided:
                voided.add(k); del punches[k]; applied += 1
        elif a == "set":
            if k in punches and k not in voided:
                punches[k][2] = iso_epoch(c["time"]); applied += 1
        elif a == "add":
            if k not in existed:
                existed.add(k)
                punches[k] = [c["employee"], c["type"].upper(), iso_epoch(c["time"])]
                applied += 1

    byemp = {}
    for (site, pid), (emp, dr, ts) in punches.items():
        if emp in emps:
            byemp.setdefault(emp, []).append((ts, 0 if dr == "OUT" else 1, site, pid, dr))

    res = {}
    exc = {"open_shifts": 0, "orphan_outs": 0, "duplicates_dropped": 0, "corrections_applied": applied}
    for e in emps:
        res[e] = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0, gross=Fraction(0))
    for e, lst in byemp.items():
        hz = sites[emps[e]][0]
        lst.sort()
        kept = []
        last = None
        def wd(ts):
            return datetime.fromtimestamp(ts, hz).date()
        for ts, _, site, pid, dr in lst:
            if last is not None and last[1] == dr and ts - last[0] <= 300:
                r = round_punch(ts, sites[site][0])
                if pstart <= wd(r) <= pend:
                    exc["duplicates_dropped"] += 1
                continue
            r = round_punch(ts, sites[site][0])
            last = (ts, dr)
            kept.append((r, dr, site))
        shifts = []
        i = 0
        n = len(kept)
        open_in = None
        for r, dr, site in kept:
            if dr == "IN":
                if open_in is not None:
                    if pstart <= wd(open_in[0]) <= pend:
                        exc["open_shifts"] += 1
                open_in = (r, site)
            else:
                if open_in is not None and r - open_in[0] <= 16 * 3600:
                    shifts.append((open_in[0], r, open_in[1]))
                    open_in = None
                else:
                    if open_in is not None:
                        if pstart <= wd(open_in[0]) <= pend:
                            exc["open_shifts"] += 1
                        open_in = None
                    if pstart <= wd(r) <= pend:
                        exc["orphan_outs"] += 1
        if open_in is not None and pstart <= wd(open_in[0]) <= pend:
            exc["open_shifts"] += 1
        shifts = [s for s in shifts if pstart <= wd(s[0]) <= pend]
        shifts.sort()
        daily = {}
        weekly = {}
        tot = res[e]
        gross = Fraction(0)
        for a, b, site in shifts:
            day = wd(a)
            worked = max(0, (b - a) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_minutes(a, b, sites[site][0]), paid)
            dprev = daily.get(day, 0)
            daily[day] = dprev + paid
            dot = max(0, dprev + paid - 480) - max(0, dprev - 480)
            nd = paid - dot
            wk = day - timedelta(days=day.weekday())
            wprev = weekly.get(wk, 0)
            weekly[wk] = wprev + nd
            wot = max(0, wprev + nd - 2400) - max(0, wprev - 2400)
            ot = dot + wot
            reg = paid - ot
            rl = rates.get(e, [])
            rate = Fraction(0)
            for ef, rt in rl:
                if ef <= day:
                    rate = rt
            if not rate and rl and rl[0][0] > day:
                rate = rl[0][1]
            gross += rate * (reg + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60
            tot["shifts"] += 1
            tot["paid_minutes"] += paid
            tot["overtime_minutes"] += ot
            tot["night_minutes"] += night
        tot["gross"] = gross

    def money(fr):
        cents = (fr * 100 + Fraction(1, 2)).__floor__()
        return "%d.%02d" % divmod(cents, 100)

    out_emps = {}
    T = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    tg = 0
    for e, v in res.items():
        g = money(v["gross"])
        tg += int(g.replace(".", ""))
        out_emps[e] = {k: v[k] for k in T}
        out_emps[e]["gross"] = g
        for k in T:
            T[k] += v[k]
    T["gross"] = "%d.%02d" % divmod(tg, 100)
    with open(outp, "w") as f:
        json.dump({"period": {"start": period["start"], "end": period["end"]},
                   "employees": out_emps, "exceptions": exc, "totals": T}, f, indent=1)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
